        /// <summary>
        /// This method is used to get draft message Details.
        /// </summary>
        /// <param name="aiAcadmicYearId"></param>
        /// <param name="aiSchoolId"></param>
        /// <param name="aiUserId"></param>
        /// <returns></returns>
        public List<MessageDraftDetails> GetDraftDetails(int aiSchoolId, int aiAcadmicYearId, int aiUserId)
        {
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("DraftId", 0, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("SchoolId", aiSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYearId", aiAcadmicYearId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("UserId", aiUserId, SqlDbType.Int);
                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetUserDraftMessages"))
                {
                    List<MessageDraftDetails> olstMessageDrafts = new List<MessageDraftDetails>();
                    while (oSqlDataReader.Read())
                    {
                        MessageDraftDetails oMessageDraftDetails = new MessageDraftDetails();
                        oMessageDraftDetails.DraftId = Convert.ToInt32(oSqlDataReader["Id"]);
                        oMessageDraftDetails.Subject = Convert.ToString(oSqlDataReader["Subject"]);
                        oMessageDraftDetails.MessageBody = Convert.ToString(oSqlDataReader["MessageBody"]);
                        oMessageDraftDetails.DraftDate = Convert.ToDateTime(oSqlDataReader["DraftDate"]);

                        olstMessageDrafts.Add(oMessageDraftDetails);
                    }
                    return olstMessageDrafts;
                }
            }
        }

