        /// <summary>
        /// This method is used to get Daft message details for send/Edit.
        /// </summary>
        /// <param name="aiAcademicYearId"></param>
        /// <param name="aiDraftId"></param>
        /// <param name="aiSchoolId"></param>
        /// <param name="aiUserId"></param>
        /// <param name="alstMessageDraftDetails"></param>
        /// <param name="alstStandardDivisionDetails"></param>
        public MessageDraftDetails GetMessageDetailsForDraftEdit(int aiDraftId, int aiUserId, int aiSchoolId, int aiAcademicYearId, out List<StandardDivisionDetails> alstStandardDivisionDetails, out List<MessageDraftUserDetails> alstMessageDraftDetails, out List<MessageDraftUserDetails> alstMessageCCDraftDetails)
        {
            alstMessageDraftDetails = new List<MessageDraftUserDetails>();
            alstStandardDivisionDetails = new List<StandardDivisionDetails>();
            alstMessageCCDraftDetails = new List<MessageDraftUserDetails>();

            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                MessageDraftDetails oMessageDraftDetails = new MessageDraftDetails();
                oSQLServerDbUtility.AddParameter("DraftId", aiDraftId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("UserId", aiUserId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("SchoolId", aiSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYearId", aiAcademicYearId, SqlDbType.Int);

                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetDraftMessageToEdit"))
                    if (oSqlDataReader.Read())
                    {
                        oMessageDraftDetails.DraftId = Convert.ToInt32(oSqlDataReader["Id"]);
                        oMessageDraftDetails.Subject = Convert.ToString(oSqlDataReader["Subject"]);
                        oMessageDraftDetails.MessageBody = Convert.ToString(oSqlDataReader["MessageBody"]);
                        oMessageDraftDetails.DisplayText = Convert.ToString(oSqlDataReader["DisplayText"]);
                        oMessageDraftDetails.DraftDate = Convert.ToDateTime(oSqlDataReader["DraftDate"]);
                        oMessageDraftDetails.FromName = Convert.ToString(oSqlDataReader["FromName"]);
                        oMessageDraftDetails.CcDisplayText = Convert.ToString(oSqlDataReader["Cc_DisplayText"]);

                        oSqlDataReader.NextResult();

                        StandardDivisionDetails oStandardDivisionDetails;
                        while (oSqlDataReader.Read())
                        { 
                            oStandardDivisionDetails = new StandardDivisionDetails();

                            oStandardDivisionDetails.StandardDivisionId = Convert.ToInt32(oSqlDataReader["StdDivId"]);

                            alstStandardDivisionDetails.Add(oStandardDivisionDetails);
                        }

                        oSqlDataReader.NextResult();
                        MessageDraftUserDetails oMessageDraftUserDetails;
                        while (oSqlDataReader.Read())
                        {
                            oMessageDraftUserDetails = new MessageDraftUserDetails();

                            oMessageDraftUserDetails.UserId = Convert.ToInt32(oSqlDataReader["UserId"]);
                            oMessageDraftUserDetails.UserRoleId = Convert.ToInt32(oSqlDataReader["UserRoleId"]);
                            oMessageDraftUserDetails.UserName = Convert.ToString(oSqlDataReader["UserName"]);

                            alstMessageDraftDetails.Add(oMessageDraftUserDetails);
                        }

                        oSqlDataReader.NextResult();
                        MessageDraftUserDetails oMessageDraftCCUserDetails;
                        while (oSqlDataReader.Read())
                        {
                            oMessageDraftCCUserDetails = new MessageDraftUserDetails();

                            oMessageDraftCCUserDetails.UserId = Convert.ToInt32(oSqlDataReader["UserId"]);
                            oMessageDraftCCUserDetails.UserRoleId = Convert.ToInt32(oSqlDataReader["UserRoleId"]);
                            oMessageDraftCCUserDetails.UserName = Convert.ToString(oSqlDataReader["UserName"]);

                            alstMessageCCDraftDetails.Add(oMessageDraftCCUserDetails);
                        }
                    }                
                return oMessageDraftDetails;
            }
        }

