        /// <summary>
        /// Get unread message list to show in message widget.
        /// </summary>
        /// <param name="aiSchoolId"></param>
        /// <param name="aiAcademicYearId"></param>
        /// <param name="aiReceiverId"></param>
        /// <param name="aiReceiverRoleId"></param>
        /// <returns></returns>
        public static UnreadMessageDetails GetUnreadMessageList(int aiSchoolId, int aiAcademicYearId, int aiReceiverId, int aiReceiverRoleId, bool abIsServiceCall = false, string asProfilePicUpdDt = "")
        {
            UnreadMessageDetails oUnreadMessageDetails = new UnreadMessageDetails() { UnreadMessageCount = 0, UnreadMessages = new List<UnreadMessage>(), SenderPhoto = new List<SenderPhoto>(), UserProfilePicData = new List<UserProfileData>()};

            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility( aiSchoolId, aiAcademicYearId,Constants.I_ZERO, abIsServiceCall))
            {
                oSQLServerDbUtility.AddParameter("SchoolId", aiSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYearId", aiAcademicYearId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("ReceiverId", aiReceiverId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("ReceiverRoleId", aiReceiverRoleId, SqlDbType.Int);
                if (asProfilePicUpdDt != string.Empty)
                    oSQLServerDbUtility.AddParameter("ProfilePicUpdateDate", asProfilePicUpdDt.ToDateTime(), SqlDbType.DateTime);

                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetUnreadMessages"))
                {
                    while (oSqlDataReader.Read())
                    {
                        DateTime dtMessageDate = Convert.ToDateTime(oSqlDataReader["Date"]);
                        int iDays = Convert.ToInt32((DateTime.Now - dtMessageDate).TotalDays);
                        int iHours = 0;
                        int iMinutes = 0;
                        string strMessageRecievedTime = string.Empty;
                        string strHourFormat = "hh:mm tt";
                        string strDayFormat = "dd/MM/yyy hh:mm tt";

                        // if message day is less than 1 then show appropriate time in hours or minutes.
                        if (iDays < 1)
                        {
                            iHours = Convert.ToInt32((DateTime.Now - dtMessageDate).TotalHours);
                            // show time in minutes.
                            if (iHours < 1)
                            {
                                iMinutes = Convert.ToInt32((DateTime.Now - dtMessageDate).TotalMinutes);
                                if (iMinutes < 1)
                                    strMessageRecievedTime = "a moment ago";
                                else
                                    strMessageRecievedTime = iMinutes + "minutes ago";
                            }
                            else
                            {
                                // show time in hours.
                                if (iHours == 1)
                                    strMessageRecievedTime = "1 hour ago";
                                else if (iHours <= 6)
                                    strMessageRecievedTime = iHours + " hours ago";
                                else
                                    strMessageRecievedTime = dtMessageDate.ToString(strHourFormat);

                            }
                        }
                        else// show date time of message
                            strMessageRecievedTime = dtMessageDate.ToString(strDayFormat);

                        string sReturnUrl = "MessageDetailsId=$$MessageDetailsId$$&MessageReceiverDetailsId=$$MessageReceiverDetailsId$$&pIndex=0&pSortExp=Insert_Date&pSortDirc=desc&Mode=&IsReadReceiptAccepted=";
                        sReturnUrl = sReturnUrl.Replace("$$MessageDetailsId$$", oSqlDataReader["MessageDetailsId"].ToString());
                        sReturnUrl = sReturnUrl.Replace("$$MessageReceiverDetailsId$$", oSqlDataReader["MessageReceiverDetailsId"].ToString());
                        sReturnUrl = CommonUtility.EncryptQuerystring(sReturnUrl);

						// Reasult related to message details
                        oUnreadMessageDetails.UnreadMessages.Add(new UnreadMessage()
                        {
                            SenderUserId = oSqlDataReader["SenderUserId"].ToString(),
                            Subject = Convert.ToString(oSqlDataReader["Subject"]),
                            Date = strMessageRecievedTime,
                            UserName = Convert.ToString(oSqlDataReader["UserName"]),
                            ReturnUrl = sReturnUrl
                        });
						
						// Select unique message sender photo 
                        if (oUnreadMessageDetails.SenderPhoto.Any(a => a.Id == oSqlDataReader["SenderUserId"].ToString()) == false)
                        {
                            oUnreadMessageDetails.SenderPhoto.Add(new SenderPhoto()
                            {
                                Id = oSqlDataReader["SenderUserId"].ToString(),
                                Photo = oSqlDataReader["PhotoImage"] != DBNull.Value ? Convert.ToBase64String(oSqlDataReader["PhotoImage"] as byte[]) : string.Empty
                            });
                        }
                    }
					// Reasult related to message count
                    if (oSqlDataReader.NextResult())
                    {
                        while (oSqlDataReader.Read())
                        {
                            oUnreadMessageDetails.UnreadMessageCount = Convert.ToInt32(oSqlDataReader["unreadmsgCount"]);
                        }
                    }
					// Reasult related to profile pic update data
                    if (oSqlDataReader.NextResult())
                    {
                        while (oSqlDataReader.Read())
                        {
                            oUnreadMessageDetails.UserProfilePicData.Add(new UserProfileData()
                            {
                                UpdateDate = oSqlDataReader["ProfilePicUpdateDate"] != DBNull.Value ? oSqlDataReader["ProfilePicUpdateDate"].ToString() : string.Empty,
                                ProfilePicture = oSqlDataReader["ProfilePicture"] != DBNull.Value ? Convert.ToBase64String(oSqlDataReader["ProfilePicture"] as byte[]) : string.Empty
                            });
                        }
                    }
                }
            }

            return oUnreadMessageDetails;
        }

        /// <summary>
        /// This method is used for get List Of Operators.
        /// </summary>
        /// <returns></returns>
        public static List<Operator> GetOperators()
        {
            List<Operator> olstOperators = new List<Operator>();
            olstOperators.Add(new Operator { Value = 1, Text = "=" });
            olstOperators.Add(new Operator { Value = 2, Text = "<" });
            olstOperators.Add(new Operator { Value = 3, Text = "<=" });
            olstOperators.Add(new Operator { Value = 4, Text = ">" });
            olstOperators.Add(new Operator { Value = 5, Text = ">=" });
            return olstOperators;
        }

        /// <summary>
        /// This method is Used for Create Date Filter.
        /// </summary>
        /// <param name="asFilter"></param>
        /// <param name="asOperator"></param>
        /// <param name="dtDate"></param>
        /// <returns></returns>
        private string CreateFilter(string asFilter, string asOperator, DateTime dtDate)
        {
            string sFilter = "";
            if (asFilter == string.Empty && dtDate == DateTime.MinValue)
                sFilter = string.Empty;
            else
            {
                List<String> operators = GetOperators().Where(opr => opr.Value.ToString() == asOperator).Select(opr => opr.Text).ToList();
                sFilter = operators.Count > Constants.I_ZERO ? operators.First() : string.Empty;
            }
            return sFilter;
        }
    } 
